from decimal import Decimal

def split_installments(total: str, n: int) -> list[Decimal]:
    # validate n: must be int >= 1, bool rejected
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an integer >= 1")
    if n < 1:
        raise ValueError("n must be >= 1")
    # validate total: must be str parseable as finite Decimal >= 0 with <= 2 decimals
    if not isinstance(total, str):
        raise ValueError("total must be a decimal string")
    try:
        d = Decimal(total)
    except Exception:
        raise ValueError("invalid total") from None
    try:
        finite = d.is_finite()
    except Exception:
        raise ValueError("invalid total") from None
    if not finite:
        raise ValueError("total must be finite")
    if d < 0:
        raise ValueError("total must be >= 0")
    tup = d.as_tuple()
    if tup.exponent < -2:
        raise ValueError("total must have at most 2 decimal places")
    # Exact cents using integer arithmetic on the tuple (no context rounding,
    # no float). exponent >= -2 so exp+2 >= 0.
    digits = tup.digits
    if len(digits) == 0:
        total_cents = 0
    else:
        int_val = int("".join(map(str, digits))) if digits != (0,) else 0
        # Handle all-zero digits (e.g. (0,), (0,0,0)) -> 0
        # int("00..") is 0 anyway, so above works; keep general path:
        if int_val == 0:
            total_cents = 0
        else:
            total_cents = int_val * (10 ** (tup.exponent + 2))
    base, rem = divmod(total_cents, n)

    def _cents_to_decimal(cents: int) -> Decimal:
        q, r = divmod(cents, 100)
        return Decimal(f"{q}.{r:02d}")

    high = _cents_to_decimal(base + 1)
    low = _cents_to_decimal(base)
    result: list[Decimal] = []
    for i in range(n):
        if i < rem:
            result.append(high)
        else:
            result.append(low)
    return result
